module TopModule (
    input  a,
    input  b,
    input  c,
    input  d,
    output out_sop,
    output out_pos
);

    assign out_sop = (~a & ~b & c) | (c & d);
    assign out_pos = (a | c) & (c | ~d) & (~b | d) & (~a | b);

endmodule

